package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.*;
public class RootCurrentReadWiringTest {
 private String source(String n)throws Exception{return Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once",n)).replace("\r\n","\n");}
 private String between(String s,String a,String b){return s.substring(s.indexOf(a),s.indexOf(b,s.indexOf(a)));}
 @Test public void newVisibleCurrentIntentPrecedesAnySourceAndNeverConstructsActor()throws Exception{String a=between(source("DormantCaptureConfirmationActivity.java"),"private void confirmCurrentRead()","private void confirmReturnRead()");assertTrue(a.indexOf("returnReadSpent=true")<a.indexOf("approveCurrentRead"));assertTrue(a.contains("startCurrentRead"));for(String bad:new String[]{"NativeAutonomousCardRun","BackActor","RootReturnReadController","ReturnPermit",".returned("})assertFalse(bad,a.contains(bad));}
 @Test public void currentBranchReturnsBeforeOldBackConstruction()throws Exception{String r=source("CaptureSessionRuntime.java");String dispatch=between(r,"private void returnBeforeReadOnOwner()","static boolean returnReadUnpresented");assertTrue(dispatch.indexOf("if(returnReadIntent.currentOnly()){currentBeforeReadOnOwner();return;}")<dispatch.indexOf("new RootReturnReadController"));String c=between(r,"private void currentBeforeReadOnOwner()","private void returnBeforeReadOnOwner()");for(String bad:new String[]{"BackActor","RootReturnReadController",".returned(","burnReturn","issueReturnReadFrame"})assertFalse(bad,c.contains(bad));assertTrue(c.contains("readCurrentTemplate(shape)"));assertTrue(c.contains("ReviewBingNavigation.knownClean()"));}
 @Test public void typedCurrentSourceIsRequiredBeforeFirstGrant()throws Exception{String r=between(source("CaptureSessionRuntime.java"),"private void currentBeforeReadOnOwner()","private void returnBeforeReadOnOwner()");assertTrue(r.indexOf("returnReadIntent.anchorCurrent(read.source(),now)")<r.indexOf("issueCurrentReadFrame("));assertTrue(r.contains("read.source().fresh("));String i=source("RootReturnReadIntent.java");assertTrue(i.contains("anchorCurrent(BingNavigationSnapshot.CurrentTemplateSource proof,long now)"));assertTrue(i.contains("proof.ready().kind()!=BingNavigationSnapshot.Kind.TEMPLATE"));assertTrue(i.contains("if(!currentOnly||readEnd!=0"));assertTrue(i.contains("if(currentOnly||readEnd!=0"));}
 @Test public void noCurrentCapabilityCanReachOldBackOrOldIssuer()throws Exception{assertTrue(source("RootReturnReadController.java").contains("if(i.currentOnly())throw new SecurityException"));String v=source("VisibleCaptureAuthority.java");for(String n:new String[]{"issueReturnReadIntent(","issueReturnReadFrame(","issueBoundedIntent(","issueSeriesIntent("}){int x=v.indexOf(n);assertTrue(v.substring(x,v.indexOf("}",x)).contains("RootCurrentCardScope.ACTIVE"));}assertTrue(v.contains("i.live()||i.currentOnly()"));assertTrue(v.contains("i.live()||!i.currentOnly()"));}
 @Test public void currentClaimSelectsNewNamespaceAndKeepsParentAndPhaseDeadline()throws Exception{String r=source("CaptureSessionRuntime.java"),i=source("RootReturnReadIntent.java");assertTrue(r.contains("returnReadIntent.currentOnly()?RootCurrentCardScope.store("));assertTrue(i.contains("currentOnly?RootCurrentCardScope.current("));assertTrue(i.contains("readEnd=Math.min(RootCurrentCardScope.deadline(now,utc.getAsLong(),end)"));assertTrue(i.contains("now,readEnd,live"));assertTrue(r.contains("new RootCurrentReadPermit(this)"));String permit=between(r,"static final class RootCurrentReadPermit","private void currentBeforeReadOnOwner()");assertTrue(permit.contains("reads>=3"));assertTrue(permit.contains("run.returnReadIntent.currentOnly()"));}
 @Test public void independentCurrentReportNeverClaimsOldReturnSucceeded()throws Exception{String r=between(source("CaptureSessionRuntime.java"),"private void currentBeforeReadOnOwner()","private void returnBeforeReadOnOwner()");assertTrue(r.contains("currentOnly=true independentCurrentRead=true returnInvoked=false oldBusinessContinued=false"));assertFalse(r.contains("templateReturned=true"));String u=source("RootCaptureUi.java");assertTrue(u.contains("零Back、零任务点击"));assertTrue(u.contains("02:25 至 03:30"));assertTrue(u.contains("不是v32返回成功"));}
 @Test public void fixtureIntentHasExplicitCurrentModeAndCannotBorrowLegacyGrant(){var e=new RealCaptureClaim.ProcessEpoch();Object owner=new Object();var i=VisibleCaptureAuthority.fixtureCurrentReadIntent(new Object(),new Object(),e,new Object(),1000,()->RootCurrentCardScope.STARTS_UTC+1000);assertTrue(i.currentOnly());assertFalse(i.live());assertEquals(51000,i.sessionEnd());assertEquals(0,i.readDeadline());try{VisibleCaptureAuthority.fixtureReturnReadGrant(i,1,e,owner,1000,null);fail();}catch(SecurityException expected){}try{VisibleCaptureAuthority.fixtureCurrentReadGrant(i,1,e,owner,1000,null);fail();}catch(SecurityException expected){}assertEquals(0,i.readDeadline());}
}
